export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"id","term":"Fully diluted valuation (FDV)","aka":["FDV","valuasi terdilusi penuh"],"short":"Fully diluted valuation (FDV) adalah perkiraan nilai sebuah proyek kripto jika seluruh suplai maksimal tokennya sudah beredar, dihitung dari harga saat ini dikali suplai maksimal atau total.","body":[["Banyak token baru diluncurkan dengan sebagian kecil suplai yang beredar, sementara sisanya terkunci untuk tim, investor awal, ekosistem, atau hadiah. ",["Market cap","market-capitalization"]," hanya menghitung yang beredar, sedangkan FDV menghitung semuanya. Selisih besar antara keduanya menunjukkan masih banyak token yang akan masuk ke pasar."],["FDV berguna untuk menilai tekanan jual di masa depan. Jika market cap 100 juta dolar tetapi FDV 1 miliar dolar, berarti hanya sekitar 10% token yang beredar. Setiap jadwal ",["token unlock","token-unlock"]," bisa menambah suplai dan menekan harga jika penerimanya menjual."],"Situs data bisa menghitung FDV dengan suplai maksimal atau suplai total, tergantung data proyek. Untuk token tanpa batas suplai, FDV menjadi kurang bermakna. Selalu cek dari mana angka suplainya berasal."],"example":["Misalkan sebuah token baru diperdagangkan di 0,40 ",["USDT","usdt"],". ",["Suplai beredar","circulating-supply"]," 150 juta token, sehingga market cap-nya 60 juta USDT. Suplai maksimalnya 1 miliar token, sehingga FDV-nya 400 juta USDT. Artinya baru 15% token yang beredar. Jika dalam setahun suplai beredar naik menjadi 400 juta token dan harga tetap 0,40 USDT, market cap akan naik menjadi 160 juta USDT, yang berarti butuh tambahan permintaan besar hanya untuk menahan harga di level yang sama."],"mistakes":["Hanya melihat market cap yang kecil lalu menganggap token masih murah, tanpa melihat FDV yang jauh lebih besar.","Tidak memeriksa jadwal token unlock untuk tim dan investor awal.","Membandingkan FDV antarproyek tanpa memastikan keduanya memakai definisi suplai yang sama."],"faq":[{"q":"Apa beda market cap dan FDV?","a":"Market cap memakai suplai yang beredar saat ini, sedangkan FDV memakai suplai maksimal atau total. FDV menggambarkan nilai jika semua token sudah dilepas ke pasar."},{"q":"Apakah FDV tinggi itu buruk?","a":"Tidak selalu, tetapi rasio market cap terhadap FDV yang rendah berarti masih banyak token yang akan dibuka. Hal ini bisa menjadi tekanan jual jika permintaan tidak ikut tumbuh."}],"title":"Apa itu FDV (fully diluted valuation) di kripto?","description":"Arti FDV atau fully diluted valuation, bedanya dengan market cap, dan cara membaca risiko suplai token yang masih terkunci.","related":[["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."],["circulating-supply","Circulating supply (suplai beredar)","Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan."],["token-unlock","Token unlock","Token unlock adalah saat sejumlah token yang sebelumnya terkunci, misalnya milik tim atau investor awal, dibuka sesuai jadwal vesting sehingga bisa dipindahkan atau dijual."],["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"id","term":"Mining (penambangan kripto)","aka":["menambang","penambangan","mining kripto"],"short":"Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi.","body":[["Penambang menjalankan mesin khusus yang terus menghitung hash untuk mencari jawaban teka-teki blok. Untuk ",["Bitcoin","bitcoin"],", mesin yang dipakai adalah ASIC, perangkat yang dirancang hanya untuk algoritma SHA-256. Kartu grafis atau laptop biasa sudah tidak kompetitif untuk Bitcoin."],"Karena peluang satu penambang kecil menemukan blok sangat rendah, kebanyakan bergabung ke mining pool. Pool menggabungkan daya hash banyak anggota dan membagi imbalan sesuai kontribusi masing-masing, dikurangi biaya pool.","Untung atau ruginya penambangan bergantung pada harga koin, biaya listrik, efisiensi mesin, tingkat kesulitan jaringan, dan halving. Hati-hati dengan tawaran cloud mining yang menjanjikan hasil tetap, karena banyak yang ternyata skema penipuan."],"example":"Misalkan mesin ASIC Anda memakai daya 3.000 watt, atau 3 kWh per jam, sehingga butuh 72 kWh per hari. Dengan tarif listrik Rp1.500 per kWh, biaya listriknya Rp108.000 per hari. Jika mesin itu menghasilkan BTC senilai Rp95.000 per hari setelah biaya pool, Anda rugi Rp13.000 per hari sebelum menghitung harga mesin. Perhitungan ini menunjukkan kenapa biaya listrik sangat menentukan.","mistakes":["Membeli mesin tambang tanpa menghitung biaya listrik dan dampak halving berikutnya.","Tergiur aplikasi atau situs cloud mining yang menjanjikan keuntungan harian pasti.","Mengira penambangan memakai koin seperti staking, padahal penambangan memakai daya komputasi."],"faq":[{"q":"Apakah menambang Bitcoin di rumah masih menguntungkan?","a":"Tergantung harga BTC, tarif listrik, dan efisiensi mesin. Dengan tarif listrik rumah tangga biasa, banyak penambang kecil sulit untung, jadi hitung dulu secara rinci."},{"q":"Apa itu mining pool?","a":"Mining pool adalah kelompok penambang yang menggabungkan daya hash agar lebih sering menemukan blok. Imbalan dibagi sesuai kontribusi, sehingga pendapatan lebih stabil."}],"title":"Apa itu mining kripto? Arti penambangan","description":"Arti mining atau penambangan kripto, cara kerja ASIC dan mining pool, serta faktor biaya yang menentukan untung rugi.","related":[["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan."],["hash-rate","Hash rate","Hash rate adalah total daya komputasi yang dipakai penambang untuk mengamankan blockchain proof of work seperti Bitcoin, diukur dalam jumlah tebakan hash per detik."],["bitcoin-halving","Bitcoin halving","Bitcoin halving adalah peristiwa terjadwal kira-kira setiap empat tahun, atau tepatnya setiap 210.000 blok, ketika imbalan blok untuk penambang dipotong setengah."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"id","term":"Validator","aka":["node validator"],"short":"Validator adalah peserta jaringan proof of stake yang mengunci koin sebagai jaminan dan menjalankan software untuk mengusulkan serta mengesahkan blok baru.","body":[["Validator berperan mirip penambang pada ",["proof of work","proof-of-work"],", tetapi tanpa perlombaan komputasi. Mereka harus selalu online, memeriksa transaksi, dan memberikan suara atas blok yang sah. Sebagai imbalan, validator menerima koin baru dan sebagian biaya transaksi."],"Jika validator offline terlalu lama, ia bisa kehilangan sebagian imbalan. Jika melakukan pelanggaran serius seperti menandatangani dua blok berbeda di posisi yang sama, sebagian jaminannya dipotong lewat slashing. Inilah yang mendorong validator berperilaku jujur.",["Di ",["Ethereum","ethereum"],", menjalankan validator sendiri membutuhkan 32 ETH dan server yang andal. Di jaringan lain seperti Solana atau Cosmos, pemegang koin biasa bisa mendelegasikan koin ke validator tanpa memindahkan kepemilikan. Validator biasanya mengambil komisi dari imbalan delegator."]],"example":"Misalkan Anda mendelegasikan 2.000 token ke validator yang mengenakan komisi 5%. Jaringan memberi imbalan 120 token per tahun untuk stake Anda. Validator mengambil 5% atau 6 token, sehingga Anda menerima 114 token. Jika validator itu terkena slashing 1%, stake Anda juga ikut terpotong 20 token pada jaringan yang memberlakukan slashing untuk delegator.","mistakes":["Memilih validator hanya karena komisi 0% tanpa melihat uptime dan riwayat slashing.","Menumpuk delegasi ke validator terbesar, yang membuat jaringan lebih terpusat.","Mengira delegasi berarti menyerahkan kepemilikan koin kepada validator."],"faq":[{"q":"Berapa ETH yang dibutuhkan untuk menjadi validator Ethereum?","a":"Untuk menjalankan validator sendiri di Ethereum dibutuhkan 32 ETH. Dengan jumlah lebih kecil, Anda bisa memakai staking pool, exchange, atau liquid staking."},{"q":"Apa yang terjadi jika validator saya offline?","a":"Imbalan Anda bisa berkurang selama validator offline. Pada pelanggaran yang lebih berat, sebagian stake bisa terkena slashing, tergantung aturan jaringan."}],"title":"Apa itu validator di kripto? Arti dan perannya","description":"Pahami peran validator di jaringan proof of stake, cara imbalan dan slashing bekerja, serta cara memilih validator untuk delegasi.","related":[["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya."],["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["restaking","Restaking","Restaking adalah memakai kembali ETH atau token liquid staking yang sudah di-stake untuk ikut mengamankan layanan lain, dengan imbalan reward tambahan sekaligus risiko slashing tambahan."],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"id","term":"Trading pair (pasangan perdagangan)","aka":["pair","pasangan trading","pasangan koin"],"short":"Trading pair adalah dua aset yang diperdagangkan satu sama lain di exchange, seperti BTC/USDT, di mana harga aset pertama dinyatakan dalam satuan aset kedua.","body":[["Aset pertama disebut base asset, aset kedua disebut quote asset. Pada ",["BTC","bitcoin"],"/",["USDT","usdt"],", BTC adalah base dan USDT adalah quote. Harga 60.000 berarti 1 BTC setara 60.000 USDT. Membeli pasangan ini berarti membeli BTC dengan USDT, menjual berarti menukar BTC kembali ke USDT."],["Exchange menawarkan beberapa jenis quote: ",["stablecoin","stablecoin"]," seperti USDT atau ",["USDC","usdc"],", mata uang lokal seperti IDR, atau koin lain seperti BTC dan ",["ETH","ethereum"],". Pasangan dengan ",["likuiditas","liquidity"]," paling tinggi biasanya memakai USDT, sehingga spread lebih sempit."],"Tidak semua koin punya pasangan langsung. Jika pasangan yang Anda cari tidak tersedia, Anda mungkin perlu menukar dua kali, misalnya IDR ke USDT lalu USDT ke koin tujuan, dan setiap langkah dikenai biaya serta spread."],"example":"Misalkan Anda punya Rp3.200.000 dan ingin membeli SOL, tetapi exchange hanya menyediakan SOL/USDT. Anda membeli USDT di harga Rp16.000, mendapat 200 USDT dikurangi biaya 0,2 USDT, sisa 199,8 USDT. Lalu Anda membeli SOL di 150 USDT, mendapat sekitar 1,332 SOL sebelum biaya kedua. Dengan biaya 0,1% lagi, Anda menerima sekitar 1,3307 SOL.","mistakes":["Salah membaca arah pasangan, misalnya mengira ETH/BTC menunjukkan harga BTC dalam ETH.","Membeli lewat pasangan dengan likuiditas rendah sehingga terkena spread dan slippage besar.","Lupa bahwa menukar lewat dua pasangan berarti membayar biaya dua kali."],"faq":[{"q":"Apa arti BTC/USDT?","a":"BTC/USDT adalah pasangan perdagangan di mana harga 1 BTC dinyatakan dalam USDT. Membeli pasangan ini berarti membeli BTC dengan USDT."},{"q":"Kenapa kebanyakan pair memakai USDT?","a":"USDT adalah stablecoin dengan likuiditas besar dan nilai yang mengikuti dolar AS, sehingga memudahkan perbandingan harga dan perpindahan antar aset."}],"title":"Apa itu trading pair? Arti pasangan seperti BTC/USDT","description":"Pelajari arti trading pair, cara membaca base dan quote asset seperti BTC/USDT, dan cara memilih pasangan yang paling likuid.","related":[["spot-trading","Spot trading (perdagangan spot)","Spot trading adalah jual beli aset kripto secara langsung di harga pasar saat ini, di mana aset benar-benar berpindah ke akun Anda setelah transaksi selesai."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Perdagangan spot pertamamu: dari 100 jadi 0.002 BTC"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"id","term":"OCO order (one cancels the other)","aka":["OCO","one cancels the other"],"short":"OCO order adalah pasangan dua order, biasanya take profit dan stop loss, di mana ketika salah satunya tereksekusi, order lainnya otomatis dibatalkan.","body":[["OCO adalah singkatan dari one cancels the other. Pada spot, OCO jual biasanya terdiri dari ",["limit order","limit-order"]," di atas ",["harga pasar","last-price"]," untuk mengambil untung dan ",["stop limit","stop-limit-order"]," di bawah harga pasar untuk membatasi rugi. Mana pun yang terpicu lebih dulu, yang lain hilang dari ",["order book","order-book"],"."],"Tanpa OCO, Anda harus memasang dua order terpisah. Masalahnya, saldo koin Anda bisa terkunci dua kali atau order kedua tetap aktif setelah posisi tertutup, sehingga bisa membuka posisi yang tidak diinginkan. OCO menyelesaikan masalah ini secara otomatis.","Tidak semua exchange menyediakan OCO dengan nama yang sama. Di futures, fungsi serupa sering muncul sebagai pengaturan TP/SL pada posisi. Periksa apakah bagian stop di OCO berupa stop limit atau stop market di platform Anda."],"example":["Misalkan Anda memegang 50 DOT yang dibeli di 7,00 ",["USDT","usdt"],". Anda memasang OCO jual: limit di 8,00 USDT untuk ",["take profit","take-profit"]," dan stop limit dengan stop 6,50 dan limit 6,45 USDT. Jika harga naik ke 8,00, 50 DOT terjual dengan untung 50 USDT dan stop otomatis dibatalkan. Jika harga turun ke 6,50 lebih dulu, posisi dijual di sekitar 6,45 sampai 6,50, rugi sekitar 25 sampai 27,5 USDT, dan limit 8,00 dibatalkan."],"mistakes":["Memasang take profit dan stop loss sebagai dua order terpisah lalu lupa membatalkan salah satunya.","Tidak memeriksa bahwa bagian stop pada OCO berupa stop limit yang bisa tidak terisi.","Mengira OCO tersedia di semua exchange dan semua jenis akun."],"faq":[{"q":"Apa arti OCO di exchange kripto?","a":"OCO berarti one cancels the other, yaitu dua order yang terhubung sehingga eksekusi satu order otomatis membatalkan order lainnya."},{"q":"Apakah OCO bisa dipakai untuk membeli?","a":"Bisa. Contohnya, limit beli di bawah harga untuk membeli saat turun dan stop beli di atas harga untuk membeli saat breakout, mana pun yang terjadi lebih dulu."}],"title":"Apa itu OCO order? Arti one cancels the other","description":"Arti OCO order di kripto, cara menggabungkan take profit dan stop loss dalam satu perintah, serta contoh perhitungannya.","related":[["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["risk-reward-ratio","Rasio risk-reward (risk-reward ratio)","Rasio risk-reward adalah perbandingan antara potensi kerugian sebuah trade (jarak ke stop loss) dan potensi keuntungannya (jarak ke take profit), misalnya 1:2."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Pasar, limit, batalkan: apa yang diselesaikan masing-masing?"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"id","term":"Post-only order","aka":["post only","maker only"],"short":"Post-only order adalah limit order yang hanya boleh masuk ke order book sebagai order maker, dan otomatis dibatalkan atau disesuaikan jika akan langsung tereksekusi sebagai taker.","body":[["Biasanya ",["limit order","limit-order"]," yang harganya langsung cocok dengan order yang ada akan dieksekusi sebagai taker dan dikenai biaya taker. Dengan opsi post-only, exchange memeriksa dulu. Jika order akan langsung cocok, order ditolak atau digeser sesuai aturan platform, sehingga Anda tidak pernah membayar biaya taker."],["Post-only populer di kalangan trader aktif, ",["market maker","market-maker"],", dan pengguna ",["bot grid","grid-trading-bot"]," karena selisih ",["biaya maker dan taker","maker-taker-fees"]," bisa besar jika ",["volume trading","trading-volume"]," tinggi. Di sebagian exchange, biaya maker untuk level tertentu bahkan bisa nol atau rebate."],"Kekurangannya, saat pasar bergerak cepat, order post-only sering ditolak dan Anda bisa ketinggalan harga. Post-only tidak cocok jika Anda harus segera masuk atau keluar dari posisi."],"example":["Misalkan Anda bertransaksi 50.000 ",["USDT","usdt"]," per bulan. Dengan biaya taker 0,10%, biayanya 50 USDT. Jika semua order Anda menjadi maker dengan biaya 0,02%, biayanya hanya 10 USDT, hemat 40 USDT per bulan. Sekarang misalkan ask terbaik 25,00 USDT dan Anda mengirim post-only beli di 25,00. Karena order itu akan langsung cocok sebagai taker, exchange menolaknya, dan Anda perlu memasang di 24,99 atau lebih rendah."],"mistakes":["Memakai post-only saat butuh keluar cepat dari posisi yang merugi.","Bingung mengapa order ditolak, padahal harganya melewati harga terbaik di sisi lain order book.","Mengira post-only menjamin order pasti terisi."],"faq":[{"q":"Kenapa order post-only saya dibatalkan?","a":"Karena harga yang Anda masukkan akan langsung cocok dengan order yang sudah ada, sehingga order akan menjadi taker. Post-only menolaknya agar Anda tetap menjadi maker."},{"q":"Apakah post-only selalu lebih murah?","a":"Biaya maker umumnya lebih rendah daripada taker, tetapi order post-only bisa tidak terisi. Penghematan biaya tidak berarti jika Anda ketinggalan harga yang penting."}],"title":"Apa itu post-only order? Arti dan manfaatnya","description":"Pelajari arti post-only order, cara memastikan order menjadi maker, penghematan biaya trading, dan kapan opsi ini kurang tepat.","related":[["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["time-in-force","Time in force (GTC, IOC, FOK)","Time in force adalah pengaturan yang menentukan berapa lama sebuah order tetap aktif dan bagaimana order diperlakukan jika tidak bisa langsung terisi penuh, dengan opsi umum GTC, IOC, dan FOK."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Pasar, limit, batalkan: apa yang diselesaikan masing-masing?"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"id","term":"Biaya maker dan taker (maker-taker fee)","aka":["maker fee","taker fee","biaya trading"],"short":"Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada.","body":[["Saat Anda memasang ",["limit order","limit-order"]," yang tidak langsung tereksekusi, order itu diam di ",["order book","order-book"]," dan menunggu pasangan. Order seperti ini disebut maker karena ikut \"membuat\" pasar. Sebaliknya, ",["market order","market-order"]," atau limit order yang langsung bertemu order lain disebut taker karena \"mengambil\" ",["likuiditas","liquidity"]," yang tersedia."],["Hampir semua exchange memberi tarif maker yang lebih rendah daripada taker, karena maker membantu order book tetap tebal. Besaran tarif berbeda antar-exchange, antar-produk (spot atau futures), dan antar-level akun atau ",["VIP tier","vip-tier"],". Beberapa exchange juga memberi potongan jika Anda membayar biaya dengan token exchange atau mendaftar lewat ",["kode referral","referral-code"],"."],"Bagi trader aktif, selisih kecil ini terasa besar karena dihitung dari nilai transaksi, bukan dari keuntungan. Selalu cek halaman struktur biaya exchange Anda sebelum memilih jenis order."],"example":"Misalkan exchange mengenakan maker 0,02% dan taker 0,05% di pasar futures. Anda membuka posisi senilai 20.000 USDT dengan market order, jadi biaya taker-nya 20.000 x 0,05% = 10 USDT. Jika Anda memakai limit order post-only dan order itu terisi sebagai maker, biayanya hanya 20.000 x 0,02% = 4 USDT. Untuk buka dan tutup posisi, selisihnya 12 USDT per putaran; dengan 50 putaran sebulan, selisihnya mencapai 600 USDT.","mistakes":["Mengira limit order selalu kena tarif maker, padahal limit order yang harganya langsung bertemu order lain tetap dihitung sebagai taker.","Menghitung biaya dari modal margin, padahal biaya futures dihitung dari nilai posisi termasuk leverage.","Tidak memperhitungkan biaya saat scalping, sehingga strategi yang terlihat untung di grafik justru rugi bersih."],"faq":[{"q":"Apa bedanya maker dan taker dalam trading kripto?","a":"Maker memasang order yang menunggu di order book, sedangkan taker langsung mengeksekusi order yang sudah ada. Maker biasanya membayar biaya lebih rendah."},{"q":"Bagaimana cara memastikan order saya dihitung sebagai maker?","a":"Gunakan opsi post-only pada limit order. Jika order itu akan langsung tereksekusi sebagai taker, exchange akan membatalkannya alih-alih mengisinya."},{"q":"Apakah biaya maker bisa negatif?","a":"Di beberapa exchange dan level VIP tertentu, maker bisa mendapat rebate atau biaya negatif. Ketentuannya berbeda-beda, jadi cek tabel biaya resmi exchange Anda."}],"title":"Apa itu biaya maker dan taker? Arti dan cara hitungnya","description":"Pelajari beda biaya maker dan taker di exchange kripto, cara menghitungnya dari nilai posisi, dan cara menekan biaya trading Anda.","related":[["post-only-order","Post-only order","Post-only order adalah limit order yang hanya boleh masuk ke order book sebagai order maker, dan otomatis dibatalkan atau disesuaikan jika akan langsung tereksekusi sebagai taker."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["vip-tier","Level VIP (tingkat biaya VIP)","Level VIP adalah tingkatan biaya trading di bursa kripto yang ditentukan oleh volume perdagangan 30 hari, saldo aset, atau kepemilikan token bursa, di mana level lebih tinggi mendapat biaya maker dan taker lebih rendah."],["referral-code","Kode referral (rebate biaya)","Kode referral adalah kode undangan yang Anda masukkan saat mendaftar di bursa kripto, yang dapat memberi Anda potongan atau pengembalian sebagian biaya trading (rebate) sesuai program bursa tersebut."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"id","term":"Maintenance margin (margin pemeliharaan)","aka":["margin pemeliharaan","MM","margin minimum"],"short":"Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda.","body":[["Maintenance margin biasanya dinyatakan sebagai persentase dari nilai posisi, misalnya 0,5% untuk posisi kecil di pasangan besar seperti ",["BTC","bitcoin"],". Persentase ini naik untuk posisi yang lebih besar melalui tingkatan risiko, dan biasanya lebih tinggi untuk ",["altcoin","altcoin"]," yang kurang likuid."],["Inilah alasan ",["likuidasi","liquidation"]," terjadi sebelum margin Anda benar-benar habis. Sisa margin di atas nol dipakai untuk menutup posisi di pasar, membayar biaya likuidasi, dan menjaga ",["insurance fund","insurance-fund"],". Exchange menghitung ekuitas posisi berdasarkan ",["mark price","mark-price"],", bukan ",["harga transaksi terakhir","last-price"],"."],"Rasio margin di aplikasi exchange menunjukkan seberapa dekat posisi Anda dengan batas ini. Saat rasio mendekati 100%, Anda punya pilihan: menambah margin, mengurangi posisi, atau menutupnya."],"example":"Anda long ETH senilai 20.000 USDT dengan margin awal 2.000 USDT (10x). Maintenance margin untuk ukuran ini misalnya 0,5%, yaitu 100 USDT. Artinya, likuidasi terjadi saat kerugian mencapai sekitar 2.000 - 100 = 1.900 USDT, bukan 2.000. Kerugian 1.900 USDT dari posisi 20.000 berarti harga turun 9,5%. Jika Anda masuk di 3.000, harga likuidasi sekitar 2.715 USDT, sebelum memperhitungkan biaya.","mistakes":["Mengira likuidasi baru terjadi saat margin benar-benar nol.","Lupa bahwa posisi besar dikenai maintenance margin lebih tinggi dan likuidasinya lebih dekat.","Mengabaikan rasio margin di aplikasi sampai posisi sudah terlambat diselamatkan."],"faq":[{"q":"Apa yang terjadi jika margin turun di bawah maintenance margin?","a":"Exchange akan melikuidasi posisi, sebagian atau seluruhnya, untuk mencegah kerugian melebihi jaminan. Beberapa exchange melakukan likuidasi bertahap untuk posisi besar."},{"q":"Di mana saya bisa melihat persentase maintenance margin?","a":"Biasanya di halaman spesifikasi kontrak atau tabel tingkatan risiko di exchange. Angkanya berbeda per pasangan dan per ukuran posisi."}],"title":"Apa itu maintenance margin? Arti dan kaitannya dengan likuidasi","description":"Pelajari maintenance margin di futures kripto, kenapa likuidasi terjadi sebelum margin habis, dan cara membaca rasio margin.","related":[["initial-margin","Margin awal (initial margin)","Margin awal adalah jumlah jaminan minimum yang harus Anda setor untuk membuka posisi dengan leverage, biasanya sama dengan nilai posisi dibagi leverage yang dipilih."],["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin."],["margin-call","Margin call","Margin call adalah peringatan bahwa jaminan di akun atau posisi Anda sudah mendekati batas minimum, sehingga Anda perlu menambah margin atau mengurangi posisi agar tidak dilikuidasi."],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Mengapa posisi Anda bisa ditutup sebelum margin Anda menyentuh nol?"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"id","term":"Reduce-only order","aka":["reduce only","order reduce-only","hanya kurangi posisi"],"short":"Reduce-only order adalah opsi order di futures yang memastikan order hanya bisa mengurangi atau menutup posisi yang sudah ada, dan tidak akan pernah membuka posisi baru atau menambah posisi ke arah sebaliknya.","body":[["Tanpa opsi ini, order jual yang lebih besar dari posisi long Anda bisa menutup long lalu membuka short dengan sisa jumlahnya. Ini sering terjadi tanpa disadari, misalnya saat Anda memasang beberapa ",["take profit","take-profit"]," atau ",["stop loss","stop-loss"],", lalu posisi sudah ditutup sebagian secara manual. Reduce-only mencegah hal itu."],"Jika ukuran order reduce-only lebih besar dari posisi yang tersisa, exchange akan menyesuaikan atau membatalkan sisanya, tergantung aturan platform. Jika posisi sudah tertutup, order reduce-only yang masih menggantung biasanya dibatalkan otomatis.","Opsi ini sangat berguna untuk take profit bertahap, stop loss, dan saat Anda memakai mode one-way. Di hedge mode, banyak exchange memperlakukan order penutupan sebagai close secara otomatis, sehingga tampilannya bisa berbeda. Cek label opsi di aplikasi exchange Anda."],"example":["Anda memegang long 1 ",["ETH","ethereum"]," di 3.100 ",["USDT","usdt"]," dan memasang dua limit sell: 0,5 ETH di 3.300 dan 1 ETH di 3.400. Harga naik ke 3.300 dan order pertama terisi, sehingga posisi tersisa 0,5 ETH. Saat harga mencapai 3.400, order kedua tanpa reduce-only akan menjual 1 ETH: 0,5 ETH menutup long dan 0,5 ETH membuka short baru. Dengan reduce-only, order itu hanya menjual 0,5 ETH dan posisi Anda tertutup bersih dengan total untung 250 USDT sebelum biaya."],"mistakes":["Memasang beberapa order take profit tanpa reduce-only sehingga total ukurannya melebihi posisi.","Lupa membatalkan order lama setelah menutup posisi secara manual, lalu order itu membuka posisi baru.","Mengira reduce-only menjamin eksekusi, padahal limit order tetap bisa tidak terisi."],"faq":[{"q":"Kapan sebaiknya memakai reduce-only?","a":"Setiap kali tujuan order adalah mengambil untung atau memotong rugi dari posisi yang sudah ada. Ini mencegah order tak sengaja membuka posisi berlawanan."},{"q":"Apakah reduce-only bisa dipakai di trading spot?","a":"Umumnya tidak. Reduce-only adalah fitur futures dan margin karena di spot Anda tidak bisa membuka posisi short dengan menjual melebihi saldo."}],"title":"Apa itu reduce-only order? Arti dan cara memakainya","description":"Pelajari reduce-only order di futures kripto: cara mencegah order membuka posisi baru, contoh take profit bertahap, dan kesalahan umum.","related":[["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["long-and-short","Posisi long dan short","Posisi long adalah posisi yang untung saat harga naik, sedangkan posisi short adalah posisi yang untung saat harga turun; keduanya bisa dibuka di futures maupun margin trading."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit dan stop-loss adalah rencana, bukan asuransi"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"id","term":"Alamat dompet (wallet address)","aka":["wallet address","alamat wallet","alamat deposit","alamat kripto"],"short":"Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu.","body":[["Alamat dihasilkan dari ",["public key","public-key"]," dan formatnya berbeda di tiap jaringan. Alamat ",["Ethereum","ethereum"],", BNB Smart Chain, Arbitrum, dan jaringan EVM lain diawali 0x. Alamat Tron diawali T, alamat ",["Bitcoin","bitcoin"]," bisa diawali 1, 3, atau bc1, dan alamat Solana berupa string panjang tanpa awalan khusus."],["Hal yang sering membingungkan pemula: satu alamat 0x yang sama bisa dipakai di beberapa jaringan EVM, tetapi saldo di tiap jaringan terpisah. ",["USDT","usdt"]," yang dikirim lewat Arbitrum tidak akan muncul jika Anda memeriksa alamat itu di Ethereum."],["Transaksi ",["blockchain","blockchain"]," tidak bisa dibatalkan, jadi alamat harus benar sampai karakter terakhir. Selalu salin dan tempel, jangan mengetik manual, lalu cocokkan beberapa karakter awal dan akhir. Untuk penarikan rutin, simpan alamat di daftar whitelist exchange agar tidak perlu menyalin ulang setiap kali."]],"example":["Anda ingin menarik 500 USDT dari exchange ke ",["dompet pribadi","non-custodial-wallet"]," lewat jaringan Tron. Alamat dompet Anda diawali TQ8 dan diakhiri xP2. Anda menempelkannya di formulir penarikan, memeriksa awal dan akhir alamat, lalu memilih jaringan TRC20. Sebelum mengirim 500 USDT, Anda mencoba 10 USDT terlebih dahulu. Setelah 10 USDT tiba, sisanya 490 USDT dikirim dengan tenang."],"mistakes":["Mengirim ke alamat yang benar tetapi memilih jaringan yang berbeda dari jaringan dompet penerima.","Menyalin alamat dari riwayat transaksi, yang bisa saja berisi alamat palsu hasil address poisoning.","Hanya memeriksa beberapa karakter awal tanpa melihat karakter akhir."],"faq":[{"q":"Apakah alamat dompet aman dibagikan?","a":"Ya, alamat dirancang untuk dibagikan agar orang bisa mengirim dana. Namun ingat bahwa siapa pun bisa melihat saldo dan riwayat alamat itu di block explorer."},{"q":"Apa yang terjadi jika saya salah alamat?","a":"Jika alamatnya valid tetapi milik orang lain, dana hampir mustahil kembali kecuali pemiliknya bersedia mengembalikan. Jika alamatnya tidak valid, dompet atau exchange biasanya menolak transaksi."}],"title":"Apa itu alamat dompet kripto? Arti wallet address","description":"Arti alamat dompet kripto, format alamat di berbagai jaringan, dan cara memeriksa alamat sebelum mengirim aset.","related":[["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."],["memo-tag","Memo / destination tag","Memo atau destination tag adalah kode tambahan selain alamat yang dipakai beberapa jaringan, seperti XRP, Stellar, TON, atau Cosmos, untuk menandai akun penerima di dalam satu alamat bersama milik exchange."],["address-poisoning","Address poisoning (peracunan alamat)","Address poisoning adalah penipuan di mana pelaku mengirim transaksi bernilai kecil atau nol dari alamat yang mirip dengan alamat yang sering Anda pakai, berharap Anda menyalin alamat palsu itu dari riwayat transaksi."],["withdrawal-whitelist","Whitelist penarikan (withdrawal whitelist)","Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"id","term":"Phishing (penipuan pancingan)","aka":["phising","penipuan phishing","situs palsu"],"short":"Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya.","body":[["Bentuknya beragam: email peringatan palsu, iklan di mesin pencari yang mengarah ke situs tiruan, akun media sosial yang menyamar sebagai admin, DM yang menawarkan ",["airdrop","airdrop"],", sampai aplikasi palsu di toko aplikasi. Domain tiruan sering hanya beda satu huruf atau memakai ekstensi berbeda."],["Di dunia kripto ada dua target utama. Pertama, kredensial akun exchange seperti kata sandi dan kode ",["2FA","two-factor-authentication"],". Kedua, ",["dompet non-kustodian","non-custodial-wallet"],": penipu meminta ",["seed phrase","seed-phrase"]," dengan dalih sinkronisasi, atau membujuk Anda menghubungkan dompet lalu menandatangani ",["token approval","token-approval"]," yang memberi mereka izin menguras token."],["Pertahanan yang paling efektif bersifat kebiasaan. Simpan bookmark situs resmi, jangan login dari tautan di email atau DM, aktifkan ",["kode anti-phishing","anti-phishing-code"],", dan baca setiap permintaan tanda tangan di dompet. Ingat bahwa tim dukungan resmi tidak pernah meminta seed phrase atau kode 2FA."]],"example":"Anda mencari nama sebuah DEX di mesin pencari dan mengklik hasil teratas yang ternyata iklan. Situsnya terlihat sama persis, tetapi domainnya memakai huruf l kecil sebagai pengganti huruf I. Anda menghubungkan dompet dan muncul permintaan approval tanpa batas untuk USDT. Jika disetujui, kontrak penipu bisa mengambil seluruh 900 USDT di dompet. Karena Anda memeriksa domain dan membaca permintaan itu, Anda menolak dan menutup tab.","mistakes":["Mengklik iklan teratas di mesin pencari tanpa memeriksa domain resmi.","Mengikuti tautan dukungan dari orang yang menghubungi Anda lebih dulu lewat DM.","Menyetujui permintaan tanda tangan di dompet tanpa membaca isinya."],"faq":[{"q":"Bagaimana cara mengenali situs phishing kripto?","a":"Periksa ejaan domain huruf demi huruf, buka situs dari bookmark, dan curigai halaman yang meminta seed phrase atau approval tidak biasa. Situs resmi tidak pernah meminta seed phrase."},{"q":"Apa yang harus dilakukan jika saya sudah memasukkan seed phrase di situs palsu?","a":"Anggap dompet itu sudah bocor. Segera buat dompet baru dengan seed phrase baru dan pindahkan semua aset yang tersisa ke sana."}],"title":"Apa itu phishing kripto? Ciri-ciri dan cara menghindarinya","description":"Kenali arti phishing di kripto, bentuk-bentuknya, dan kebiasaan sederhana untuk melindungi akun exchange dan dompet Anda.","related":[["anti-phishing-code","Kode anti-phishing","Kode anti-phishing adalah kata atau kode rahasia yang Anda tetapkan di akun exchange, lalu dicantumkan di setiap email resmi exchange agar Anda bisa membedakannya dari email palsu."],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."],["token-approval","Token approval (izin token)","Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui."],["address-poisoning","Address poisoning (peracunan alamat)","Address poisoning adalah penipuan di mana pelaku mengirim transaksi bernilai kecil atau nol dari alamat yang mirip dengan alamat yang sering Anda pakai, berharap Anda menyalin alamat palsu itu dari riwayat transaksi."],["pig-butchering-scam","Penipuan pig butchering","Pig butchering adalah penipuan jangka panjang di mana pelaku membangun hubungan pertemanan atau asmara dengan korban, lalu membujuknya berinvestasi kripto di platform palsu sampai seluruh dana diambil."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"id","term":"Proof of reserves (bukti cadangan)","aka":["PoR","bukti cadangan","proof of reserves"],"short":"Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree.","body":[["Setelah runtuhnya FTX pada akhir 2022, banyak exchange mulai menerbitkan laporan proof of reserves secara berkala. Umumnya ada dua sisi. Sisi aset menunjukkan ",["alamat dompet","wallet-address"]," milik exchange yang bisa diperiksa di ",["blockchain","blockchain"],". Sisi kewajiban menunjukkan total saldo pengguna, sering dalam bentuk Merkle tree."],"Dengan Merkle tree, Anda bisa memverifikasi bahwa saldo akun Anda termasuk dalam total yang dilaporkan tanpa melihat saldo pengguna lain. Rasio cadangan di atas 100% berarti exchange mengklaim memegang lebih banyak aset daripada kewajibannya untuk koin tersebut.","Proof of reserves punya batas. Laporan menangkap kondisi pada satu waktu, tidak selalu memperlihatkan utang atau kewajiban lain di luar saldo pengguna, dan kualitasnya bergantung pada metode serta pihak yang memverifikasi. Anggap PoR sebagai satu sinyal transparansi, bukan jaminan penuh keamanan dana."],"example":["Misalnya sebuah exchange mencatat total saldo ",["BTC","bitcoin"]," pengguna sebesar 40.000 BTC dan menunjukkan alamat dompet yang berisi 42.000 BTC. Rasio cadangannya 42.000 dibagi 40.000, yaitu 105%. Anda lalu membuka alat verifikasi di akun, melihat saldo Anda 0,3 BTC tercatat di dalam Merkle tree laporan tersebut, dan memastikan tanggal laporannya masih baru."],"mistakes":["Menganggap rasio cadangan di atas 100% berarti exchange tidak mungkin bermasalah.","Tidak memeriksa tanggal laporan sehingga memakai data yang sudah usang.","Mengabaikan sisi kewajiban dan hanya melihat besarnya saldo di dompet exchange."],"faq":[{"q":"Apakah proof of reserves menjamin dana saya aman?","a":"Tidak sepenuhnya. PoR menunjukkan aset dan saldo pengguna pada satu titik waktu, tetapi tidak selalu mencakup semua utang atau risiko operasional exchange."},{"q":"Bagaimana cara memeriksa saldo saya di proof of reserves?","a":"Banyak exchange menyediakan menu verifikasi di akun yang menampilkan hash saldo Anda dan jalur Merkle-nya, yang bisa dicocokkan dengan laporan publik."}],"title":"Apa itu proof of reserves? Arti bukti cadangan exchange","description":"Pelajari arti proof of reserves, cara kerja Merkle tree dan rasio cadangan, serta batasan laporan PoR exchange kripto.","related":[["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."],["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."],["insurance-fund","Insurance fund (dana asuransi)","Insurance fund adalah cadangan dana milik exchange futures yang dipakai untuk menutup kerugian ketika posisi yang dilikuidasi ditutup di harga lebih buruk dari harga kebangkrutannya, sehingga trader lain tidak ikut menanggung."],["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"id","term":"Crypto Earn (produk simpanan kripto)","aka":["Earn","Simple Earn","tabungan kripto"],"short":"Crypto Earn adalah kategori produk di bursa yang memberi imbal hasil atas aset kripto yang Anda simpan, misalnya simpanan fleksibel, simpanan berjangka, staking, atau produk terstruktur.","body":["Nama produknya berbeda di setiap bursa, seperti Simple Earn, Savings, atau Earn. Simpanan fleksibel bisa ditarik kapan saja dengan imbal hasil yang berubah-ubah. Simpanan berjangka mengunci aset selama periode tertentu dengan imbal hasil yang biasanya lebih tinggi.",["Sumber imbal hasil bervariasi: pinjaman ke trader margin, hadiah ",["staking","staking"]," jaringan, aktivitas ",["DeFi","defi"]," yang dikelola bursa, atau subsidi promosi. Angka yang ditampilkan biasanya ",["APR","apr-vs-apy"]," atau APY tahunan dan sering berubah. Produk terstruktur seperti ",["dual investment","dual-investment"]," memiliki risiko yang jauh berbeda dari simpanan biasa."],"Karena aset dititipkan ke bursa, Anda menanggung risiko kustodian. Jika bursa bermasalah, dana bisa tertahan. Simpanan kripto juga bukan tabungan bank dan tidak dijamin lembaga penjamin simpanan. Baca aturan penarikan, periode kunci, dan batas jumlah untuk tingkat imbal hasil tertinggi."],"example":["Misalkan Anda menyimpan 2.000 ",["USDT","usdt"]," di produk fleksibel dengan APR 5%. Imbal hasil harian kira-kira 2.000 kali 5% dibagi 365, sekitar 0,27 USDT per hari, atau sekitar 8,2 USDT per bulan. Namun banyak bursa memberi APR tinggi hanya untuk porsi pertama, misalnya 500 USDT pertama di 8% dan sisanya 3%. Dengan skema itu, imbal hasil tahunan menjadi 40 ditambah 45, yaitu 85 USDT, atau setara sekitar 4,25%, bukan angka tertinggi yang terpampang di iklan."],"mistakes":["Melihat APR tertinggi tanpa membaca batas jumlah yang berlaku untuk angka itu.","Mengunci aset di produk berjangka padahal mungkin butuh dana sewaktu-waktu.","Menganggap produk Earn sama aman dengan tabungan bank yang dijamin."],"faq":[{"q":"Dari mana bursa membayar imbal hasil Earn?","a":"Biasanya dari bunga pinjaman margin, hadiah staking, aktivitas DeFi, atau promosi bursa. Sumbernya berbeda per produk, jadi baca penjelasan produk sebelum menyetor."},{"q":"Apakah simpanan fleksibel bisa ditarik kapan saja?","a":"Umumnya bisa, meski beberapa bursa memproses penebusan dalam waktu tertentu atau membatasi saat permintaan tinggi. Produk berjangka tidak bisa ditarik sebelum jatuh tempo atau dikenai kehilangan imbalan."}],"title":"Apa itu Crypto Earn? Produk simpanan kripto di bursa","description":"Pelajari jenis produk Earn di bursa kripto, sumber imbal hasilnya, cara menghitung APR berjenjang, dan risikonya.","related":[["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama."],["dual-investment","Dual investment (investasi ganda)","Dual investment adalah produk terstruktur bursa yang memberi imbal hasil tinggi, tetapi saat jatuh tempo Anda bisa menerima aset yang berbeda dari yang disetor, tergantung harga terhadap target."],["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"id","term":"P2P trading (jual beli P2P)","aka":["P2P","C2C","peer-to-peer","jual beli P2P"],"short":"P2P trading adalah jual beli kripto langsung antarpengguna di platform bursa, di mana pembayaran rupiah dilakukan lewat transfer bank atau e-wallet dan kripto penjual ditahan sistem escrow.","body":["Prosesnya: penjual memasang iklan dengan harga dan metode pembayaran. Pembeli memilih iklan, lalu kripto penjual dikunci di escrow. Pembeli mentransfer rupiah langsung ke rekening penjual, menandai sudah membayar, lalu penjual melepas kripto setelah dana benar-benar masuk.",["P2P populer sebagai jalur masuk dan keluar fiat di bursa global, terutama untuk ",["USDT","usdt"],". Harga P2P bisa sedikit berbeda dari kurs pasar karena penjual menetapkan harganya sendiri. Biaya platform untuk pengguna biasa sering rendah atau nol, tetapi kebijakannya berbeda antarbursa."],"Risiko utamanya adalah penipuan pembayaran: bukti transfer palsu, dana dari rekening pihak ketiga, atau pembayaran yang belakangan ditarik kembali. Jangan pernah melepas kripto sebelum mengecek mutasi rekening sendiri, jangan bertransaksi di luar platform, dan pastikan nama pengirim sama dengan nama akun."],"example":"Misalkan Anda ingin membeli 300 USDT lewat P2P. Iklan A menawarkan Rp16.200 per USDT dengan minimal transaksi Rp1.000.000, iklan B Rp16.100 tetapi penjualnya baru dengan 3 transaksi selesai. Dengan iklan A Anda membayar Rp4.860.000, dengan iklan B Rp4.830.000, selisih Rp30.000. Banyak pembeli memilih iklan A karena riwayat penjualnya ratusan transaksi dengan tingkat penyelesaian tinggi. Setelah transfer, tekan sudah dibayar dan tunggu penjual melepas USDT dari escrow ke akun Anda.","mistakes":["Melepas kripto hanya berdasarkan tangkapan layar bukti transfer.","Setuju melanjutkan transaksi lewat chat di luar platform.","Menerima pembayaran dari rekening atas nama orang lain."],"faq":[{"q":"Apakah P2P aman?","a":"Relatif aman jika Anda bertransaksi di platform dengan escrow, memilih pedagang berreputasi, dan memeriksa mutasi rekening sendiri. Sebagian besar kasus penipuan terjadi saat aturan ini dilanggar."},{"q":"Apa beda P2P dan C2C?","a":"Keduanya merujuk pada jual beli langsung antarpengguna. Beberapa bursa memakai nama C2C, sedangkan yang lain memakai P2P."}],"title":"Apa itu P2P trading kripto? Cara aman jual beli P2P","description":"Pelajari cara kerja P2P atau C2C di bursa kripto, peran escrow, cara memilih pedagang, dan modus penipuan umum.","related":[["fiat-on-ramp","Fiat on-ramp","Fiat on-ramp adalah layanan atau jalur untuk menukar uang biasa seperti rupiah menjadi aset kripto, misalnya lewat transfer bank, kartu, e-wallet, atau P2P di bursa."],["usdt","USDT (Tether)","USDT adalah stablecoin yang diterbitkan Tether dan dirancang bernilai 1 dolar AS, serta menjadi stablecoin dengan peredaran terbesar dan pasangan perdagangan paling umum di exchange kripto."],["pig-butchering-scam","Penipuan pig butchering","Pig butchering adalah penipuan jangka panjang di mana pelaku membangun hubungan pertemanan atau asmara dengan korban, lalu membujuknya berinvestasi kripto di platform palsu sampai seluruh dana diambil."],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"Deposit pertama: dari mana uang masuk dan ke mana perginya?"},"coin":null,"tool":null,"cta":true}});
